        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 25,
        marker = "***",
        depth = 3,
        instruction = "When he's immune to magical damage (his magic stance), he will mainly cast BLM spells such as elemental debuffs and tier 2 AoE nukes. He also has a weaponskill, Dark Nova (AoE dark damage).",
